/// whose body can hold a plaintext key or item attribute values.
/// Its `Display` chain holds neither.
struct SourceText<'a>(&'a (dyn std::error::Error + 'static));

impl fmt::Debug for SourceText<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let mut text = self.0.to_string();
        let mut link = self.0.source();
        while let Some(e) = link {
            text.push_str(": ");
            text.push_str(&e.to_string());
            link = e.source();
        }
        fmt::Debug::fmt(&text, f)
    }
}

/// Write `level`, leaving out what it repeats from `prev`.
fn write_level(
    f: &mut fmt::Formatter<'_>,
    level: &Level<'_>,
    prev: Option<&Level<'_>>,
) -> fmt::Result {
    if prev.is_none_or(|p| p.name != level.name) {
        write!(f, "{}: ", level.name)?;
    }
    f.write_str(level.message)?;
    let details: Vec<&str> = level
        .details
        .iter()
        .filter(|d| prev.is_none_or(|p| !p.details.contains(d)))
        .map(String::as_str)
        .collect();
    let mut parts = Vec::new();
    if !details.is_empty() {
        parts.push(details.join(", "));
    }
    if !level.data_keys.is_empty() && prev.is_none_or(|p| p.data_keys != level.data_keys) {
        parts.push(format!("message has: {}", level.data_keys.join(", ")));
    }
    if !parts.is_empty() {
        write!(f, " ({})", parts.join("; "))?;
    }
    if !level.tried.is_empty() {
        write!(f, "; tried: {}", level.tried.join(", "))?;
    }
    Ok(())
}

/// Write `top`, then each error in its source chain.
fn write_chain<'a>(
    f: &mut fmt::Formatter<'_>,
    top: Level<'a>,
    mut source: Option<&'a (dyn std::error::Error + 'static)>,
) -> fmt::Result {
    write_level(f, &top, None)?;
    let mut prev = top;
    loop {
        if !prev.collected.is_empty() {
            write!(f, ": {} errors: [", prev.collected.len())?;
            for (i, c) in prev.collected.iter().enumerate() {
                if i > 0 {
                    f.write_str("; ")?;
                }
                write!(f, "{c:#}")?;
            }
            return f.write_str("]");
        }
        let Some(s) = source else {
            return Ok(());
        };
        f.write_str(": ")?;
        if let Some(level) = level_of(s) {
            write_level(f, &level, Some(&prev))?;
            prev = level;
        } else {
            write!(f, "{s}")?;
        }
        source = s.source();
    }
}

/// `{}` writes `Variant: message (details)`; `{:#}` adds the source chain.
fn write_error(
    f: &mut fmt::Formatter<'_>,
    data: &ErrorData,
    name: &'static str,
    remote: bool,
) -> fmt::Result {
    let level = data.level(name, remote);
    if f.alternate() {
        write_chain(f, level, data.source())
    } else {
        write_level(f, &level, None)
    }
}

