    /// Every failure behind this error, at any depth, as this crate's `Error`.
    ///
    /// Each collected error is replaced by its own failures, so nested collections are flattened.
    /// When this error collects nothing, it uses the first collection in its source chain.
    /// An error with no collection anywhere in its source chain yields itself.
    #[must_use]
    pub fn failures(&self) -> Vec<Self> {
        if !self.collected().is_empty() {
            return self.collected().iter().flat_map(Self::failures).collect();
        }
        let mut link = std::error::Error::source(self);
        while let Some(e) = link {
            if let Some(e) = e.downcast_ref::<Self>()
                && !e.collected().is_empty()
            {
                return e.failures();
            }
            if let Some(e) = e.downcast_ref::<aws_crypto_mpl::Error>()
                && !e.collected().is_empty()
            {
                return e
                    .collected()
                    .iter()
                    .flat_map(|c| Self::from_mpl_parts(c).failures())
                    .collect();
            }
            if let Some(e) = e.downcast_ref::<aws_mpl_primitives::Error>()
                && !e.collected().is_empty()
            {
                return e
                    .collected()
                    .iter()
                    .flat_map(|c| Self::from_prim_parts(c).failures())
                    .collect();
            }
            link = e.source();
        }
        vec![self.clone()]
    }

