    /// The first error of type `T` in the source chain, starting with `self`.
    ///
    /// ```
    /// use aws_db_esdk::Error;
    ///
    /// fn handle(err: &Error) {
    ///     if let Some(io) = err.find_source::<std::io::Error>() {
    ///         println!("{io}");
    ///     }
    /// }
    /// ```
    #[must_use]
    pub fn find_source<T: std::error::Error + 'static>(&self) -> Option<&T> {
        let mut link: Option<&(dyn std::error::Error + 'static)> = Some(self);
        while let Some(e) = link {
            if let Some(found) = e.downcast_ref::<T>() {
                return Some(found);
            }
            link = e.source();
        }
        None
    }

